window.VOICE = {"engine":"files:/home/user/skyde/video/seslendirme/Nefes","gain":1.25,"lines":[{"id":"n-hook","say":"Soğukta ağzından çıkan o duman, aslında duman değil; az önce kendi yaptığın minicik bir bulut.","at":0.1,"dur":6.526,"marks":[0,2.28,3.8]},{"id":"n-buhar","say":"Ciğerlerinden çıkan nefes ılık ve su buharıyla dolu. Sıfır derecedeki hava ise bunun ancak sekizde biri kadar suyu taşıyabiliyor.","at":7.276,"dur":8.206,"marks":[0,3.74]},{"id":"n-damla","say":"Nefesin soğuk havaya çarpınca, fazla su sığacak yer bulamıyor ve minicik damlacıklara dönüşüyor. Gökteki bulutlar da böyle oluşuyor.","at":16.332,"dur":7.987,"marks":[0,2.12,6.24]},{"id":"n-kayip","say":"Birkaç saniye sonra kaybolması da bundan: Damlacıklar etraftaki kuru havaya karışıp yeniden görünmez buhara dönüyor.","at":25.369,"dur":7.002,"marks":[0,2.62]},{"id":"n-bardak","say":"Üstelik sen bu suyu yaz kış veriyorsun: Günde bir buçuk, iki su bardağı kadar. Kış sadece onu görünür yapıyor.","at":33.171,"dur":6.907,"marks":[0,2.5,3.38,4.86]},{"id":"n-cta","say":"Kışın ejderha gibi duman üfleyen arkadaşına gönder.","at":40.928,"dur":3.775,"marks":[0]}],"audio":""};
